    int b = blockIdx.z;                     // batch index
    int c = blockIdx.y * 32 + threadIdx.y; // output channel (grid: 32*16 channels per row)
    int h = blockIdx.x * 16 + threadIdx.x; // height out
    int w = threadIdx.z? Not defined. We'll compute width via another dimension.

    if (b < batch_size && c < out_channels && h < height_out && w < width_out) {
