                int ih = h * stride + ki - padding;
                int iw = w * stride + kj - padding;
                if (ih >= 0 && ih < height_in && iw >= 0 && iw < width_in) {
                    // depth‑wise: use the same input channel as output channel modulo in_channels
                    int ic = c % in_channels;
                    float val = input[b * in_channels * height_in * width_in + ic * height_in * width_in + h * width_in + w * height_in];
                    sum += weight[c * kernel_size * kernel_size * height_in * width_in + ic * kernel_size * kernel_size + ... ]; // placeholder
                }
            }
        }
    }
}

torch::Tensor conv2d_cuda(torch::Tensor input, torch::Tensor weight) {
    auto size = input.numel();
    auto out = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    conv2d_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), weight.data_ptr<float>(), out.data_ptr<float>(),
